public class DOMNodePointer_equals_TriageGen0Test {

    @Test
    public void testEquals_SameInstance() {
        Node mockNode = mock(Node.class);
        DOMNodePointer pointer = new DOMNodePointer(mockNode, Locale.ENGLISH);

        // Test branch: if (object == this) return true;
        Assert.assertTrue("An object should be equal to itself", pointer.equals(pointer));
    }

    @Test
    public void testEquals_NullObject() {
        Node mockNode = mock(Node.class);
        DOMNodePointer pointer = new DOMNodePointer(mockNode, Locale.ENGLISH);

        // Test branch: if (!(object instanceof DOMNodePointer)) return false; (null case)
        Assert.assertFalse("Null should not be equal to pointer", pointer.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        Node mockNode = mock(Node.class);
        DOMNodePointer pointer = new DOMNodePointer(mockNode, Locale.ENGLISH);
        String differentObject = "Not a DOMNodePointer";

        // Test branch: if (!(object instanceof DOMNodePointer)) return false;
        Assert.assertFalse("Different class should not be equal", pointer.equals(differentObject));
    }

    @Test
    public void testEquals_SameNodeDifferentPointers() {
        Node mockNode = mock(Node.class);
        DOMNodePointer pointer1 = new DOMNodePointer(mockNode, Locale.ENGLISH);
        DOMNodePointer pointer2 = new DOMNodePointer(mockNode, Locale.ENGLISH);

        // Test branch: return node == other.node; (true case)
        Assert.assertTrue("Pointers with the same node should be equal", pointer1.equals(pointer2));
    }

    @Test
    public void testEquals_DifferentNodes() {
        Node node1 = mock(Node.class);
        Node node2 = mock(Node.class);
        DOMNodePointer pointer1 = new DOMNodePointer(node1, Locale.ENGLISH);
        DOMNodePointer pointer2 = new DOMNodePointer(node2, Locale.ENGLISH);

        // Test branch: return node == other.node; (false case)
        Assert.assertFalse("Pointers with different nodes should not be equal", pointer1.equals(pointer2));
    }

    @Test
    public void testEquals_UsingOtherConstructors() {
        Node mockNode = mock(Node.class);
        DOMNodePointer pointer1 = new DOMNodePointer(mockNode, Locale.ENGLISH, "id1");
        DOMNodePointer pointer2 = new DOMNodePointer(mockNode, Locale.ENGLISH, "id2");

        // Ensure equality logic relies on the node, not the ID
        Assert.assertTrue("Equality should be based on the node reference", pointer1.equals(pointer2));
    }

    @Test
    public void testEquals_ParentConstructor() {
        Node mockNode = mock(Node.class);
        DOMNodePointer parent = new DOMNodePointer(mockNode, Locale.ENGLISH);
        DOMNodePointer child = new DOMNodePointer(parent, mockNode);

        // Test the third constructor and equality
        Assert.assertTrue("Child pointer should be equal to a pointer wrapping the same node", 
                child.equals(new DOMNodePointer(mockNode, Locale.ENGLISH)));
    }
}
